package com.example.webapptemplate;
import com.example.webapptemplate.ai.internal.application.*;import com.example.webapptemplate.ai.AiCheckResult.Status;import com.example.webapptemplate.settings.FeaturePolicy;import com.example.webapptemplate.platform.ImageCodec;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AiTextTests {
 @Test void enforcesPermissionAndModelBeforeCallingProvider(){var gateway=mock(GeminiGateway.class);var policy=mock(FeaturePolicy.class);var codec=mock(ImageCodec.class);var useCase=new GenerateText(gateway,policy,codec);var id=UUID.randomUUID();when(gateway.model()).thenReturn("gemini-test");assertThat(useCase.generate(id,"instruction","input",List.of()).state()).isEqualTo("DISABLED");verify(gateway,never()).generateMany(anyString(),anyString(),anyList());when(policy.aiEnabled()).thenReturn(true);when(gateway.configured()).thenReturn(true);assertThat(useCase.generate(id,"instruction","input",List.of()).state()).isEqualTo("MODEL_DENIED");verify(gateway,never()).generateMany(anyString(),anyString(),anyList());when(policy.allowsAiModel("gemini-test")).thenReturn(true);when(gateway.generateMany(anyString(),anyString(),anyList())).thenReturn(new GeminiGateway.Generated(Status.RATE_LIMIT,""));assertThat(useCase.generate(id,"instruction","input",List.of()).state()).isEqualTo("RATE_LIMIT");assertThatThrownBy(()->useCase.generate(id,"instruction"," ",List.of())).isInstanceOf(IllegalArgumentException.class);}
}
